const text=($input.first().json.body||{}).text;
if(!text||!String(text).trim()){return [{json:{success:false,error:'Ders notu bos olamaz.'}}];}
const sys='Sen bir universite sinav hazirlama asistanisin. Verilen ders notundan TAM 5 adet coktan secmeli soru uret. Sorular sadece nottaki bilgilere dayansin. Her soruda 4 secenek olsun ve yalnizca biri dogru olsun. correct_answer degeri options listesindeki bir secenekle birebir ayni olmali. Sadece su JSON yapisini dondur: {"questions":[{"question":"...","topic":"kisa konu basligi","options":["...","...","...","..."],"correct_answer":"...","explanation":"..."}]}';
return [{json:{ollamaBody:{model:'qwen2.5:7b',stream:false,format:'json',options:{temperature:0.3,num_ctx:8192},messages:[{role:'system',content:sys},{role:'user',content:String(text)}]}}}];

const j=$input.first().json;
const fail=(m)=>[{json:{success:false,error:m}}];
if(!j.message||!j.message.content){return fail('Yapay zeka yanit veremedi.');}
let d;try{d=JSON.parse(j.message.content);}catch(e){return fail('Yapay zeka gecerli test uretemedi. Tekrar deneyin.');}
const qs=Array.isArray(d.questions)?d.questions:[];
const ok=qs.filter(q=>q&&typeof q.question==='string'&&Array.isArray(q.options)&&q.options.length===4&&q.options.includes(q.correct_answer)&&typeof q.explanation==='string');
if(ok.length<5){return fail('Yeterli sayida gecerli soru uretilemedi. Tekrar deneyin.');}
return [{json:{success:true,questions:ok}}];
